// =====================================================================
// PUNTO UNICO DE SALIDA. Todas las ramas convergen aca.
//
// Existe por una trampa concreta de n8n: despues de un nodo HTTP, $json
// pasa a ser la RESPUESTA del request, no tus datos. Si cada nodo de
// Chatwoot leyera $('Rama X'), reventaria en las ramas que no pasaron
// por X. Con un solo nodo comun, todos leen $('Armar salida') y siempre
// existe.
//
// Ademas es lo que permite tener UN nodo por accion (responder, notar,
// etiquetar) en vez de uno por rama.
// =====================================================================
return $input.all().map((item) => {
  const j = item.json || {};

  // OJO: POST /labels de Chatwoot REEMPLAZA el set completo, no agrega.
  // Sin este merge, cualquier etiqueta que un agente puso a mano se pierde
  // en el proximo turno del bot.
  const base = j.modo === 'general' ? 'consulta-general' : 'reactivacion';
  const nuevas = Array.isArray(j.etiquetas) && j.etiquetas.length ? j.etiquetas : [base];
  const previas = Array.isArray(j.etiquetas_previas) ? j.etiquetas_previas : [];
  const etiquetas = [];
  for (const e of previas.concat(nuevas)) {
    const t = (e || '').toString().trim();
    if (t && etiquetas.indexOf(t) === -1) etiquetas.push(t);
  }

  return { json: {
    conversation_id: j.conversation_id,
    telefono: j.telefono || '',
    nombre: j.nombre || '',
    empresa: j.empresa || '',
    motivo_perdida: j.motivo_perdida || '',
    input: j.input || j.texto || '',
    modo: j.modo || 'normal',
    paso: j.paso || '',
    cierre: j.cierre || '',
    agendado: j.agendado === true,
    slot: (j.slot_final || j.slot_elegido || {}).etiqueta || '',
    email_final: j.email_final || '',
    mensaje_saliente: (j.mensaje_saliente || '').toString(),
    etiquetas: etiquetas,
    nota_agenda: (j.nota_agenda || '').toString(),
    // Se avisa al comercial cuando la conversacion pasa a una persona o
    // cuando hay reunion. Se deriva de la ETIQUETA, no de un campo suelto:
    // toda rama que promete "lo contacta un integrante del equipo" pone
    // 'necesita-humano', asi no hay forma de prometerlo y no avisar.
    avisar: etiquetas.indexOf('necesita-humano') !== -1 || j.agendado === true
  } };
});

// =====================================================================
// PROCESAR RESPUESTA — traduce lo que devolvio el modelo en algo que
// Chatwoot entienda: mensaje, etiquetas y motivo de cierre.
//
// Desde que el agendamiento lo hace el propio agente con sus herramientas,
// aca ya no se dispara ninguna rama: solo se LEE lo que paso. El unico
// dato nuevo es el marcador [AGENDADO], que el modelo agrega cuando la
// herramienta de Calendly le confirmo la reunion.
// =====================================================================
const MSG_ESCALAR = 'Esa consulta la puede responder mejor un especialista de nuestro equipo. Le derivo la conversacion y se comunican a la brevedad.';

// =====================================================================
// SE USA .first(), NO .item.
//
// '.item' es busqueda por PAIRED ITEM: n8n rastrea la genealogia del item
// hacia atras por todo el grafo. En el camino hay un AI Agent, que no
// propaga esa metadata, y este nodo ademas tiene DOS entradas (la rama del
// agente y la rama 'fija'). Resultado: n8n se colgaba minutos buscando la
// correspondencia, sin error y sin timeout.
//
// '.first()' es una referencia directa al primer item y resuelve al toque.
// Es correcto ACA por una invariante del flujo: un webhook = un mensaje =
// un item. El buffer de rafagas ademas garantiza que solo UNA ejecucion
// contesta. Si algun dia entraran varios mensajes por ejecucion, esto hay
// que volver a pensarlo -- por eso queda escrito.
// =====================================================================
let pre = {};
try { pre = $('Preparar Datos Lead').first().json || {}; } catch (e) { pre = {}; }

// =====================================================================
// CANDADO: si 'Preparar Datos Lead' bloqueo la conversacion (opt-out,
// audio sin texto o tope de turnos), la respuesta es FIJA. Ni siquiera se
// mira la salida del modelo. Es la unica forma de garantizar el
// comportamiento: un candado legal no se le pide por favor a un modelo.
// =====================================================================
if (pre.bloqueado) {
  return { json: Object.assign({}, pre, {
    mensaje_saliente: pre.respuestaFija || '',
    // 'sin_texto' no es una escalacion: el cliente mando un audio y se le
    // pidio que lo escriba. La conversacion sigue abierta y normal.
    etiquetas: pre.bloqueado === 'optout'
      ? [pre.modo === 'general' ? 'consulta-general' : 'reactivacion', 'opt-out', 'no-contactar']
      : (pre.bloqueado === 'sin_texto'
          ? [pre.modo === 'general' ? 'consulta-general' : 'reactivacion']
          : [pre.modo === 'general' ? 'consulta-general' : 'reactivacion', 'necesita-humano']),
    cierre: pre.bloqueado === 'optout' ? 'baja'
      : (pre.bloqueado === 'sin_texto' ? '' : 'escalado'),
    agendado: false,
    nota_agenda: ''
  }) };
}

let r = '';
try {
  const item = $input.item.json || {};
  r = (item.output || item.text || item.response || '').toString();
} catch (e) { r = ''; }
r = r.trim();

// Si el modelo no contesto (sin credito, 429, timeout) va a un humano.
// El modelo ESCRIBIO el nombre de la herramienta en vez de llamarla.
// Sin esto, al cliente le llega un WhatsApp que dice
// "agendar_reunion_calendly". Las tools tienen "calendly" al final, asi
// que el patron matchea en los dos ordenes.
const nombroLaTool = /(consultar|agendar)[a-z_ -]*calendly|calendly[ \t_-]*(consultar|agendar)/i.test(r);

let escalar = !r || r.indexOf('Error fetching') !== -1 || r.indexOf('429') !== -1 || nombroLaTool;
let agendado = false;

// FUERA DE TEMA: preguntas ajenas al negocio (la receta de hamburguesa).
// Se desvia con cortesia y la conversacion SIGUE ABIERTA. Va ANTES del
// chequeo de ESCALAR: no se le hace perder el tiempo a un humano con algo
// que ningun humano del equipo iba a contestar tampoco.
// OJO: el texto de abajo NO puede contener "especialista", "derivar" ni
// "escalar" -- la red de seguridad que sigue lo convertiria en MSG_ESCALAR.
let fueraDeTema = false;
if (/\bfuera[_ ]?de[_ ]?tema\b/i.test(r)) {
  fueraDeTema = true;
  escalar = false;
  r = 'Me voy a limitar a los temas de gestion de facturas y gastos, que es donde puedo serle util. Como viene hoy esa parte en ' + (pre.empresa || 'su empresa') + '?';
}

// =====================================================================
// [AGENDADO]: el modelo llamo a la herramienta de Calendly y le confirmo.
// Es un marcador de control, no texto para el cliente: se saca siempre.
//
// Se evalua ANTES de la red anti-escalacion. Un mensaje de "quedo agendada
// la reunion" es un exito, no una derivacion, y algunas confirmaciones
// nombran al comercial que va a estar en la llamada -- sin este orden,
// esa palabra convertiria el cierre bueno en MSG_ESCALAR.
// =====================================================================
if (!fueraDeTema && /\[\s*agendado\s*\]/i.test(r)) {
  agendado = true;
  escalar = false;
  r = r.replace(/\[\s*agendado\s*\]/ig, '').replace(/\s+/g, ' ').trim();
  // Si el marcador se comio todo el mensaje, algo salio mal en la redaccion.
  if (!r) r = 'Listo, quedo agendada la reunion. Le llega la invitacion por correo.';
}

if (!fueraDeTema && !agendado && !escalar) {
  // El modelo casi nunca devuelve ESCALAR literal: lo parafrasea
  // ("Necesito escalar su consulta..."). Verificado en pruebas reales.
  if (/\bescalar\b|\bderiv(o|ar|amos)\b|\bespecialista\b/i.test(r)) escalar = true;

  // Ultima red: si se puso a especular igual, o rompio el personaje
  // hablando de si mismo como IA, se deriva.
  if (/no tengo (informaci|datos)|no cuento con|como (IA|modelo)|puedo inferir|probablemente sea/i.test(r)) {
    escalar = true;
  }
}

const mensaje = escalar ? MSG_ESCALAR : r;

// Motivo de cierre. 'escalado' = lo toma un humano. 'despedida' = termino bien.
let cierre = '';
if (agendado) cierre = 'agendado';
else if (escalar) cierre = 'escalado';
else if (/\badi[oó]s\b|hasta pronto|quedamos a disposicion|le agradezco la respuesta/i.test(mensaje)) {
  cierre = 'despedida';
}

// Etiquetas de Chatwoot segun como termino el turno.
// 'agendado' es TERMINAL: 'Preparar Datos Lead' la lee y el bot no vuelve
// a hablar en esa conversacion.
const BASE = pre.modo === 'general' ? 'consulta-general' : 'reactivacion';
let etiquetas = [BASE];
if (agendado) etiquetas = [BASE, 'agendado'];
else if (escalar) etiquetas = [BASE, 'necesita-humano'];

// La nota privada queda solo como candado y rastro de auditoria: ya no
// lleva maquina de estados, porque el horario y el mail viven en el hilo.
const nota = agendado
  ? 'AGENDA_ESTADO ' + JSON.stringify({ etapa: 'agendado', registrado: new Date().toISOString() })
  : '';

return { json: Object.assign({}, pre, {
  mensaje_saliente: mensaje,
  etiquetas: etiquetas,
  cierre: cierre,
  fuera_de_tema: fueraDeTema,
  agendado: agendado,
  nota_agenda: nota
}) };

const CFG = $('Config').first().json;
const MAX_TURNOS_HIST = parseInt(CFG.WA_MAX_TURNOS) || 12;
const MAX_TURNOS = parseInt(CFG.WA_MAX_TURNOS_BOT) || 0;   // 0 = sin tope

const KIND = (CFG.CALENDLY_LOCATION_KIND || '').toString().toLowerCase();
const MODALIDAD = KIND.indexOf('zoom') !== -1 ? 'Es una videollamada por Zoom'
  : KIND.indexOf('google') !== -1 ? 'Es una videollamada por Google Meet'
  : KIND.indexOf('teams') !== -1 ? 'Es una videollamada por Microsoft Teams'
  : KIND.indexOf('physical') !== -1 ? 'Es presencial'
  : 'Es una videollamada';
const INSTALAR = KIND.indexOf('physical') !== -1
  ? 'No aplica, la reunion es presencial.'
  : 'Con el link del correo alcanza. Si le ofrece descargar una aplicacion, puede entrar igual desde el navegador.';

const OPT_OUT = [
  /\bdar(me|nos)? de baja\b(?!\s+(a\s+)?(un|una|el|la|los|las|mi|su)?\s*(usuario|proveedor|factura|comprobante|cuenta|articulo|producto|empleado|centro|item|orden)\w*)/i,
  /\bsolicito la baja\b|\bbaja de la (lista|base)\b/i,
  /\b(stop|unsubscribe|desuscribir|desuscribime)\b/i,
  /no me (escrib|contact|manden|mande|llamen|molest)/i,
  /dejen de (escrib|molest|contact|mandar)/i,
  /\b(borr|elimin|sa[cq]|quit)\w*me\b/i,
  /(borren|elimin\w*|saquen|quiten)\s+(me|mi|mis)\b/i,
  /no quiero (que me|recibir|mas mensaje)/i,
  /reportar como spam|es spam|esto es spam/i
];
const MSG_OPT_OUT = 'Entendido. Damos de baja el contacto y no volveremos a escribirle. Disculpe la molestia.';
const MSG_TOPE = 'Prefiero que siga la conversacion un integrante del equipo comercial, que le va a poder dar mas detalle. Ya le paso el contacto.';
const MSG_SIN_TEXTO = 'Perdon, no puedo escuchar audios ni ver imagenes por este canal. Me lo escribe y lo vemos?';

const ETIQUETAS_TERMINALES = ['opt-out', 'no-contactar', 'necesita-humano', 'escalado'];

const limpiar = s => (s || '').toString().replace(/\s+/g, ' ').trim();

const metas = $('Cruzar con contexto del CRM').all();
const salida = [];

$input.all().forEach((item, idx) => {
  const meta = (metas[idx] && metas[idx].json) || {};
  const b = item.json || {};

  let msgs = [];
  if (Array.isArray(b.payload)) msgs = b.payload;
  else if (Array.isArray(b)) msgs = b;
  else if (b.payload && Array.isArray(b.payload.payload)) msgs = b.payload.payload;

  if (!msgs.length) return;

  let agenda = {};
  for (const m of msgs) {
    const c = (m.content || '').toString();
    if (m.private !== true || c.indexOf('AGENDA_ESTADO ') !== 0) continue;
    try {
      const d = JSON.parse(c.slice('AGENDA_ESTADO '.length));
      if (d && d.etapa) agenda = d;
    } catch (e) { /* nota rota: se ignora */ }
  }

  let turnos = [];
  for (const m of msgs) {
    if (m.private === true) continue;
    const tipo = m.message_type;
    if (tipo === 2 || tipo === 'activity') continue;
    const t = limpiar(m.content);
    if (!t) continue;
    turnos.push({ rol: (tipo === 0 || tipo === 'incoming') ? 'CLIENTE' : 'NOSOTROS', texto: t });
  }

  const idsEntrantes = msgs
    .filter(m => m.private !== true && (m.message_type === 0 || m.message_type === 'incoming'))
    .map(m => parseInt(m.id) || 0);
  const idUltimo = idsEntrantes.length ? Math.max.apply(null, idsEntrantes) : 0;
  const idPropio = parseInt(meta.message_id) || 0;

  if (idPropio && idUltimo && idUltimo > idPropio) return;

  let turnoCliente = 0;
  let previo = '';
  for (const t of turnos) {
    if (t.rol === 'CLIENTE' && previo !== 'CLIENTE') turnoCliente++;
    previo = t.rol;
  }
  turnoCliente = turnoCliente || 1;

  const rafaga = [];
  for (let i = turnos.length - 1; i >= 0; i--) {
    if (turnos[i].rol !== 'CLIENTE') break;
    rafaga.unshift(turnos[i].texto);
  }
  const recorte = turnos.slice(-MAX_TURNOS_HIST);
  const transcripcion = recorte.map(t => t.rol + ': ' + t.texto).join('\n');

  const textoCliente = rafaga.length ? rafaga.join('. ') : limpiar(meta.texto);
  const etiquetas = (meta.etiquetas || []).map(e => e.toString().toLowerCase().trim());
  const emailCrm = /^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$/i.test((meta.email || '').trim())
    ? meta.email.trim().toLowerCase() : '';

  const turnosModelo = turnoCliente;
  const paso = turnoCliente <= 1 ? 1 : (turnoCliente === 2 ? 2 : 3);

  const telDigitos = (meta.telefono || '').toString().replace(/[^0-9]/g, '');
  const DATOS_QA = { empresa: meta.empresa || '', nombre: meta.nombre || '',
    telefono: meta.telefono || '', telefono_e164: telDigitos ? '+' + telDigitos : '',
    sistema: meta.sistema || '', pais: meta.pais || '' };
  const calendly_qa = (Array.isArray(CFG.CALENDLY_PREGUNTAS) ? CFG.CALENDLY_PREGUNTAS : [])
    .map(function (q) {
      const resp = (q.respuesta || '').toString().replace(/\{(\w+)(?:\|([^}]*))?\}/g, function (_, k, def) {
        const v = (DATOS_QA[k] || '').toString().trim();
        return v || (def || '').toString();
      }).trim();
      const o = { question: (q.pregunta || '').toString(), answer: resp };
      if (q.position !== undefined) o.position = q.position;
      return o;
    })
    .filter(function (q) { return q.question && q.answer; });

  let accion = 'bot';
  let bloqueado = '';
  let respuestaFija = '';
  let modo = 'normal';

  const terminal = ETIQUETAS_TERMINALES.find(e => etiquetas.indexOf(e) !== -1);
  const yaAgendado = etiquetas.indexOf('agendado') !== -1 || agenda.etapa === 'agendado';

  if (terminal) {
    return;
  } else if (!textoCliente) {
    accion = 'fija'; bloqueado = 'sin_texto'; respuestaFija = MSG_SIN_TEXTO;
  } else if (OPT_OUT.some(re => re.test(textoCliente))) {
    accion = 'fija'; bloqueado = 'optout'; respuestaFija = MSG_OPT_OUT;
  } else if (MAX_TURNOS > 0 && turnosModelo > MAX_TURNOS) {
    accion = 'fija'; bloqueado = 'tope'; respuestaFija = MSG_TOPE;
  } else if (meta.conocido === false) {
    modo = 'general';
  } else if (yaAgendado) {
    modo = 'postventa';
  }

  const TIPOS = { normal: 'REACTIVACION', postventa: 'POST_AGENDAMIENTO', general: 'CONSULTA_GENERAL' };
  const tipoConversacion = TIPOS[modo] || 'REACTIVACION';

  let ficha;
  if (modo === 'general') {
    ficha = '- No esta en el piloto. No tenemos ningun dato de esta persona.';
  } else {
    const L = [];
    const push = (k, v) => { const x = limpiar(v); if (x) L.push('- ' + k + ': ' + x); };
    push('Nombre', meta.nombre);
    push('Empresa', meta.empresa);
    push('Pais', meta.pais);
    push('Sistema ERP', meta.sistema);
    push('Facturas mensuales', meta.cantidad_facturas);
    push('Comercial que lo atendio', meta.owner);

    const hitos = [];
    if (limpiar(meta.fecha_discovery)) hitos.push('discovery el ' + limpiar(meta.fecha_discovery));
    if (limpiar(meta.hubo_reunion) === 'si') hitos.push('tuvo reunion con el equipo');
    if (limpiar(meta.fecha_propuesta)) hitos.push('se le envio propuesta el ' + limpiar(meta.fecha_propuesta));
    if (hitos.length) L.push('- Historia con nosotros: ' + hitos.join('; '));

    const dias = parseInt(meta.dias_desde_perdida);
    if (!isNaN(dias)) L.push('- Se marco como perdida hace ' + dias + ' dias');

    if (limpiar(meta.motivo_perdida)) {
      L.push('- Lo ultimo que nos dijeron (textual, respetalo): "' + limpiar(meta.motivo_perdida) + '"');
    } else {
      L.push('- No quedo registrado el motivo de la perdida. NO inventes uno.');
    }
    ficha = L.join('\n') || '- Sin datos adicionales en el CRM.';
  }

  salida.push({ json: Object.assign({}, meta, {
    accion: accion,
    bloqueado: bloqueado,
    respuestaFija: respuestaFija,
    input: textoCliente,
    paso: paso,
    turnoCliente: turnoCliente,
    turnos_modelo: turnosModelo,
    tipo_conversacion: tipoConversacion,
    nombre_corto: meta.primer_nombre || 'Contacto',
    ficha: ficha,
    modalidad: MODALIDAD,
    instalar: INSTALAR,
    email_crm: emailCrm,
    transcripcion: transcripcion,
    modo: modo,
    calendly_qa: calendly_qa,
    agenda_etapa: agenda.etapa || ''
  }) });
});

return salida;

// =====================================================================
// CRUCE CON EL CRM. Antes esto era un candado: el que no estaba en la
// lista del piloto se descartaba. Ya no, porque el bot tambien contesta
// consultas generales de gente que nunca estuvo en el piloto.
//
// Lo que hace ahora es CLASIFICAR, no filtrar:
//   conocido: true  -> lead del piloto, con toda su historia comercial
//   conocido: false -> consulta general, sin ficha y sin pitch
//
// Quien protege de pisarle la conversacion a una persona es el candado
// del asignado, en 'Filtrar solo entrantes'.
// =====================================================================
const soloDigitos = s => (s || '').toString().replace(/[^0-9]/g, '');

// Compara los ultimos 8 digitos: sortea diferencias de prefijo pais / 9 / 15
const cola = s => { const d = soloDigitos(s); return d.length >= 8 ? d.slice(-8) : ''; };

const porTel = {};
const porConv = {};
try {
  for (const it of $('Leer Enviados WA').all()) {
    const r = it.json;
    const c = cola(r.telefono);
    if (c) porTel[c] = r;
    const conv = (r.chatwoot_conversation_id || '').toString().trim();
    if (conv) porConv[conv] = r;
  }
} catch (e) {}

// PUERTA DE PRUEBA: estos telefonos entran como leads del piloto aunque
// no tengan una fila en la hoja ni atributos en Chatwoot. Sin esto caen en
// modo 'general', y en ese modo el prompt le PROHIBE al modelo usar las
// herramientas de Calendly -- o sea que no se podria probar el agendamiento.
// Se comparan los ultimos 8 digitos, igual que el resto del cruce.
const PRUEBA = new Set(
  ((($('Config').first().json || {}).WA_TELEFONOS_PRUEBA) || [])
    .map(t => cola(t)).filter(Boolean)
);

const txt = v => (v === null || v === undefined) ? '' : String(v);
const salida = [];

for (const it of $('Filtrar solo entrantes').all()) {
  const m = it.json;
  // Orden de preferencia:
  //  1) los custom_attributes que ya vinieron en el webhook (sin red)
  //  2) la fila de la hoja, si el IF de arriba la hizo leer
  const c = (m.tiene_contexto ? m.crm : null)
    || porConv[String(m.conversation_id)]
    || porTel[cola(m.telefono)]
    || null;

  // NO conocido -> consulta general. No hay ficha ni historia comercial:
  // los campos van vacios a proposito y el prompt cambia de modo.
  // La lista blanca solo AGREGA: si el numero ya estaba en el CRM, se usa
  // su ficha real. Nunca pisa datos buenos con una ficha vacia.
  const esPrueba = PRUEBA.has(cola(m.telefono));
  const conocido = !!c || esPrueba;
  const d = c || {};

  salida.push({ json: {
    conversation_id: m.conversation_id,
    telefono: m.telefono,
    texto: m.texto,
    soportado: m.soportado,
    message_id: m.message_id,
    etiquetas: m.etiquetas || [],
    etiquetas_previas: m.etiquetas || [],
    nombre: txt(d.nombre || m.nombre_wa),
    // Vacio si no hay nombre, NO 'Hola': este campo lo lee el prompt del
    // agente como el nombre del interlocutor. Con el default viejo, a un
    // contacto sin nombre en WhatsApp el modelo lo trataba de "Hola".
    primer_nombre: (txt(d.nombre || m.nombre_wa).split(' ')[0]) || '',
    empresa: txt(d.empresa),
    motivo_perdida: txt(d.motivo_perdida),
    sistema: txt(d.sistema),
    pais: txt(d.pais),
    // El atributo del correo cambio de nombre en Chatwoot y se manejaron
    // dos variantes ('emailsdk' / 'emailkdm'). Se aceptan las dos mas el
    // nombre viejo: si se lee el equivocado, el bot le pide el correo a
    // gente que ya lo tiene cargado, y eso no da ningun error visible.
    // La hoja de Sheets sigue usando la columna 'email'.
    email: txt(d.emailsdk || d.emailkdm || d.email_kdm || d.email),
    owner: txt(d.owner),
    cantidad_facturas: txt(d.cantidad_facturas),
    fecha_discovery: txt(d.fecha_discovery),
    fecha_reunion: txt(d.fecha_reunion),
    fecha_propuesta: txt(d.fecha_propuesta),
    dias_desde_perdida: txt(d.dias_desde_perdida),
    hubo_reunion: txt(d.hubo_reunion),
    calificacion: txt(d.calificacion),
    fecha_envio: txt(d.fecha_envio),
    conocido: conocido
  } });
}

return salida;

// =====================================================================
// CANDADO 1: Chatwoot NO es exclusivo de este piloto.
// El webhook message_created llega por TODA la cuenta, asi que hay que
// descartar activamente lo que no sea de este flujo.
// =====================================================================
const INBOX_PERMITIDO = ($('Config').first().json.CHATWOOT_INBOX_ID || '').toString().trim();
const salida = [];

// ⚠️ $input NO es el webhook: es el nodo 'Config', que esta en el medio y
// REEMPLAZA los items (hace return [{ json: {...} }]). Con $input.all() se
// recorria la config, message_type venia undefined y SE DESCARTABA TODO
// mensaje, siempre, sin ningun error visible.
// El payload real se lee del webhook por nombre.
for (const item of $('Chatwoot - message_created').all()) {
  const raw = item.json || {};
  const p = raw.body || raw;

  // Solo el evento que nos interesa
  if (p.event && p.event !== 'message_created') continue;

  // ANTI-LOOP: el bot no puede responderse a si mismo
  const tipo = (p.message_type || '').toString().toLowerCase();
  if (tipo !== 'incoming') continue;

  // Las notas internas de los agentes no son del cliente
  if (p.private === true) continue;

  // CANDADO por inbox: si esta configurado, solo ese inbox
  const inbox = ((p.inbox && p.inbox.id) || p.inbox_id || '').toString().trim();
  if (INBOX_PERMITIDO && inbox && inbox !== INBOX_PERMITIDO) continue;

  const texto = (p.content || '').toString().trim();
  const conv = (p.conversation && p.conversation.id) || p.conversation_id || null;
  if (!conv) continue;

  // ETIQUETAS de la conversacion: son el estado persistente del bot.
  // No hay base propia -- Chatwoot ya es el dueno del hilo y de su estado.
  // OJO: la forma exacta del payload de message_created hay que verificarla
  // contra la instancia real; por eso se leen las tres variantes conocidas.
  const cv = p.conversation || {};
  const etiquetas = []
    .concat(Array.isArray(cv.labels) ? cv.labels : [])
    .concat(Array.isArray(cv.label_list) ? cv.label_list : [])
    .concat(Array.isArray(p.labels) ? p.labels : [])
    .map(e => (e && e.title ? e.title : e).toString());

  // =================================================================
  // CLASIFICACION TEMPRANA: piloto o consulta general.
  //
  // El workflow 1 le pone 'reactivacion' a cada conversacion del piloto.
  // Si la tiene, hace falta el contexto del CRM. Si NO la tiene, es una
  // consulta general y no hay CRM que buscar: se saltea Google Sheets
  // entero. Eso es lo que evita que cada mensaje ajeno se traiga la hoja
  // completa y queme la cuota de lectura (60/min).
  const esPiloto = etiquetas.some(e => e.toLowerCase().trim() === 'reactivacion');

  // Si el payload NO trae etiquetas no podemos saber si es del piloto.
  // En ese caso NO se decide aca: se hace la busqueda en la hoja y decide
  // 'Cruzar con contexto'. Filtrar por un campo ausente dejaria al bot mudo
  // con todo el mundo y sin ningun error visible.
  const esGeneral = etiquetas.length > 0 && !esPiloto;

  // =================================================================
  // CANDADO NUEVO: NO LE PISES LA CONVERSACION A UN HUMANO.
  //
  // Este reemplaza al descarte por etiqueta. Antes, todo lo que no fuera
  // del piloto se tiraba, y eso alcanzaba como proteccion. Ahora el bot
  // TAMBIEN contesta consultas generales, asi que el unico limite que
  // queda es este: si la conversacion ya tiene un agente asignado, es de
  // el. El bot se calla.
  //
  // Solo corta cuando HAY asignado. Si el campo no viene en el payload,
  // no se descarta nada: mismo criterio defensivo que con las etiquetas.
  // =================================================================
  const cvMeta = cv.meta || {};
  const asignado = (cvMeta.assignee && cvMeta.assignee.id)
    || (cv.assignee && cv.assignee.id) || cv.assignee_id || null;
  if (asignado) continue;

  const sender = p.sender || {};

  // =================================================================
  // CONTEXTO DEL CRM, DIRECTO DEL WEBHOOK.
  // El WF1 lo deja en los custom_attributes del contacto de Chatwoot.
  // Si viene aca, el WF2 NO necesita leer la hoja de Sheets: se ahorra
  // una lectura de la API de Google por cada mensaje entrante.
  //
  // 'empresa' y 'motivo_perdida' se usan de testigo: un contacto puede
  // existir en Chatwoot sin haber pasado nunca por el WF1, y en ese caso
  // los atributos vienen vacios y hay que caer a la hoja igual.
  // =================================================================
  const attrs = (sender.custom_attributes && typeof sender.custom_attributes === 'object')
    ? sender.custom_attributes : {};
  const tieneContexto = !!(attrs.empresa || attrs.motivo_perdida);
  const tel = (sender.phone_number || sender.identifier || '').toString().replace(/[^0-9]/g, '');

  salida.push({ json: {
    conversation_id: conv,
    contact_id: sender.id || null,
    inbox_id: inbox,
    telefono: tel,
    nombre_wa: (sender.name || '').toString(),
    texto: texto,
    etiquetas: etiquetas,
    estado_conversacion: (cv.status || '').toString(),
    es_piloto: esPiloto,
    es_general: esGeneral,
    soportado: texto.length > 0,
    message_id: p.id || null,
    crm: attrs,
    tiene_contexto: tieneContexto
  } });
}

return salida;

// Unico lugar de configuracion del workflow.
// Esta instancia de n8n corre con N8N_BLOCK_ENV_ACCESS_IN_NODE: $env tira
// "access to env vars denied" y el `|| default` NO salva, porque la excepcion
// se tira al tocar $env. Por eso la config vive aca.
// Todo nodo aguas abajo lee con: $('Config').first().json.LO_QUE_SEA
return [{ json: {
  // --- Chatwoot ---
  CHATWOOT_URL: 'https://chatwoot.xtract.app',               // sin barra final
  CHATWOOT_ACCOUNT_ID: '1',
  CHATWOOT_INBOX_ID: '1',     // inbox de WhatsApp

  // --- Hoja de control del piloto ---
  WA_SHEET_URL: 'REEMPLAZAR_WA_SHEET_URL',

  // --- Avisos ---
  WA_SLACK_CHANNEL: 'REEMPLAZAR_SLACK_CHANNEL',

  // --- Calendly (Scheduling API: REQUIERE plan pago de Calendly) ---
  // Los tools del agente leen estos valores. EVENT_TYPE, la zona horaria y
  // LOCATION_KIND van fijos en el nodo tool: el modelo no los puede tocar.
  CALENDLY_EVENT_TYPE: 'https://api.calendly.com/event_types/a382fbef-fc03-4a33-ae47-90024c6b6714', // https://api.calendly.com/event_types/XXXX
  // Desde cuando se busca. 0 = desde ahora. La tool de disponibilidad la
  // usa, asi que si falta queda en 0 sin que nadie se entere.
 CALENDLY_DESDE_DIAS: 0,
  CALENDLY_DIAS: 21,              // ventana de disponibilidad (endpoint admite hasta 31)
  CALENDLY_OPCIONES: 3,           // horarios que se le piden al modelo que ofrezca
  CALENDLY_HORA_DESDE: 9,         // horario laboral ARGENTINO
  CALENDLY_HORA_HASTA: 18,
  CALENDLY_LOCATION_KIND: 'google_conference',
  // Duracion real del evento en Calendly. El bot la dice cuando le preguntan
  // "cuanto dura", asi que si cambias el event type, cambiala aca tambien.
  CALENDLY_DURACION_MIN: 30,
  CALENDLY_PREGUNTAS: [
    // La UNICA obligatoria. Es el numero de WhatsApp desde el que escribio
    // el cliente: SIEMPRE existe, porque es como llego el mensaje.
    //
    // SIN VALOR POR DEFECTO A PROPOSITO. Un numero inventado terminaria
    // escrito en la reserva real y el comercial lo leeria como si fuera el
    // del cliente. Si algun dia llegara vacio, la pregunta se omite y
    // Calendly rechaza el alta con un error visible -- que es lo correcto.
    { position: 1, pregunta: 'Número de teléfono', respuesta: '{telefono_e164}' },
    // Opcional. Se usa para dejar constancia de que la reunion la coordino
    // el bot: sin esto, el comercial la lee como una reserva normal.
    { position: 0, pregunta: 'Cuéntenos algo que nos ayude a prepararnos para la reunión.',
      respuesta: 'Reunion coordinada por el asistente de reactivacion de Closed Lost ({empresa|empresa sin identificar}, ERP: {sistema|no informado}). El cliente acepto por WhatsApp.' }
  ],
  // --- PUERTA DE PRUEBA ---
  // Numeros que entran al flujo COMPLETO aunque no esten en la hoja ni
  // tengan atributos en Chatwoot. Se los trata como leads del piloto: con
  // ficha vacia, pero con modo normal y con las herramientas de Calendly
  // habilitadas, que es lo que hace falta para probar el agendamiento.
  //
  // ⚠️ VACIAR ESTA LISTA ANTES DEL PILOTO REAL. Mientras tenga numeros,
  // esos telefonos van a ser tratados como leads aunque no lo sean.
  // [] la desactiva por completo.
  WA_TELEFONOS_PRUEBA: ['+5493624900418', '+5493624009270'],

  // --- Buffer de rafagas ---
  // En WhatsApp nadie escribe un parrafo: manda "hola" / "che" / "una
  // consulta" en 5 segundos. Cada uno dispara una ejecucion. Se espera el
  // silencio y contesta UNA sola, con todo junto.
  WA_ESPERA_RAFAGA_SEG: 8,

  // --- Barandas de la conversacion ---
  WA_MAX_TURNOS: 12,     // turnos de historial que se le pasan al modelo
  // Mensajes conversados con el modelo antes de pasarlo a un humano.
  // OJO: desde que el agendamiento lo maneja el modelo con tools, los turnos
  // de coordinar horario y confirmar el mail SI cuentan aca. Por eso 12 y no
  // 8: con 8, un cliente que esta confirmando el correo se escala solo
  // -- justo el que estaba por cerrar. 0 lo desactiva por completo.
  WA_MAX_TURNOS_BOT: 12
} }];
